def solve_small_fast(n):
    M = n * (n - 1) // 2
    # dp[d][N][M_prev] = min cost
    dp = {(0, 0): 0} # (N, M_prev) -> cost

    for d in range(1, M + 1):
        new_dp = {}
        for (N_prev, M_prev_prev), cost in dp.items():
            for s in [0, 1, 2]:
                for e in [0, 1, 2]:
                    if s + e <= 2:
                        N = N_prev + s
                        M_prev = M_prev_prev + e
                        if N - M_prev_prev >= 2 and N >= M_prev:
                            new_cost = cost + (N - M_prev_prev)
                            state = (N, M_prev)
                            if state not in new_dp or new_cost < new_dp[state]:
                                new_dp[state] = new_cost
        dp = new_dp

    return dp.get((n, n), float('inf'))

for n in range(3, 8):
    print(f"n={n}, cost={solve_small_fast(n)}")

